// ── CONFIG (editar) ─────────────────────────────────────────────
// Location ID de la subcuenta de GHL de Nuria Roure
const GHL_LOCATION_ID = 'YOUR_GHL_LOCATION_ID';
// Número(s) español(es) de Ringover (DID). Para inferir entrante/saliente.
const RINGOVER_DIDS = ['+34930523794'];

// IMPORTANTE: confirmar los nombres de campo con el PRIMER payload real.
// Activa el webhook, haz una llamada de prueba y mira el campo `raw` de la
// nota/ejecución; ajusta los mapeos de abajo si Ringover usa otros nombres.

const out = [];
for (const item of $input.all()) {
  const p = item.json.body ?? item.json;

  const event = String(p.event || p.type || p.last_state || '').toLowerCase();

  // Ringover puede usar caller_number/receiver_number o from_number/to_number
  const caller   = p.caller_number || p.from_number || p.from || '';
  const receiver = p.receiver_number || p.to_number || p.to || '';

  // Dirección: campo explícito si existe; si no, se infiere
  let direction = String(p.direction || '').toLowerCase();
  if (!direction) {
    if (event.includes('out')) direction = 'out';
    else if (event.includes('in') || event.includes('incoming')) direction = 'in';
    else if (RINGOVER_DIDS.includes(caller)) direction = 'out';
    else direction = 'in';
  }
  const isOutbound = direction.startsWith('out');

  // El teléfono del lead es "la otra parte"
  const leadPhone    = isOutbound ? receiver : caller;
  const agentNumber  = isOutbound ? caller : receiver;

  const durationSec = Number(
    p.total_duration_in_seconds ?? p.incall_duration_in_seconds ?? p.duration ?? 0
  );
  const recording = p.record || p.recording_url || p.record_url || '';
  const ts        = p.timestamp || p.start_time || p.answered_time || '';
  const agentName = (p.user && (p.user.concat_name || p.user.email)) || p.agent || '';
  const callId    = p.call_id || p.id || p.channel_id || '';

  out.push({
    json: {
      ghlLocationId: GHL_LOCATION_ID,
      event,
      callId,
      directionLabel: isOutbound ? 'Saliente' : 'Entrante',
      leadPhone,
      agentNumber,
      agentName,
      durationSec,
      durationLabel: Math.floor(durationSec / 60) + 'm ' + (durationSec % 60) + 's',
      recording,
      timestamp: ts,
      raw: p
    }
  });
}
return out;

